css:
body :where([data-bz-node="ec"]) .bz-block{padding:0}
body :where([data-bz-node="ec"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="ec"]>.bz-container{padding-inline:0}

body [data-bz-node="ec"]{background:#fff;padding:96px 0}
body [data-bz-node="ec"]>.bz-container{max-width:var(--container)}
body [data-bz-node="ec-h"] .bz-eyebrow{font:700 10.5px/1.4 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:#6b6b6a;margin:0 0 14px}
body [data-bz-node="ec-h"] h2{font:700 36px/1.08 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="ec-grid"]{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;align-items:stretch;margin-top:40px}
body [data-bz-node="ec-grid"]>.bz-col{grid-column:auto}
body [data-bz-node^="ec-card-"]{display:flex;flex-direction:column;background:#fff;border:1px solid #e4e4e2;padding:28px 30px 30px;box-sizing:border-box;min-height:140px}
body [data-bz-node^="ec-title-"] h3{font:700 20px/1.2 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0 0 16px}
body [data-bz-node^="ec-mail-"]{display:block;margin-bottom:10px}
body [data-bz-node^="ec-mail-"] .bz-text{max-width:none}
body [data-bz-node^="ec-mail-"] p{position:relative;padding-left:26px;font:400 12.5px/1.6 var(--font-body);margin:0;overflow-wrap:anywhere}
body [data-bz-node^="ec-mail-"] p::before{content:"";position:absolute;left:0;top:3px;width:14px;height:14px;background:var(--accent);-webkit-mask:url(/icons/mail.svg) center/14px no-repeat;mask:url(/icons/mail.svg) center/14px no-repeat}
body [data-bz-node^="ec-mail-"] a{color:var(--accent);text-decoration:none}
body [data-bz-node^="ec-mail-"] a:hover{text-decoration:underline}
@media (max-width:1100px){body [data-bz-node="ec"]{padding:64px 24px}body [data-bz-node="ec-h"] h2{font-size:30px}body [data-bz-node="ec-grid"]{grid-template-columns:repeat(2,1fr)}}
@media (max-width:640px){body [data-bz-node="ec"]{padding:48px 20px}body [data-bz-node="ec-h"] h2{font-size:26px}body [data-bz-node="ec-grid"]{grid-template-columns:1fr;gap:16px;margin-top:28px}body [data-bz-node^="ec-card-"]{padding:22px 22px 24px;min-height:0}}
